        assertThat(mapper.readTree(approve.getBody()).get("state").asText()).isEqualTo("APPROVED");

        // 6. 量产备案 ACTIVE
        ResponseEntity<String> filed = post("/filings",
                body(Fixtures.requestId(), Map.of("formulaId", formulaId)));
