                        + "occupied_version, certificate_id, occurred_at, request_id, created_at "
                        + "FROM controlled_production_record WHERE id = ?",
                CONTROLLED_PRODUCTION_MAPPER, id));
    } catch (EmptyResultDataAccessException e) {
        return Optional.empty();
