 * 服务层响应模型集合；所有金额类字段单位 g/kg，时间字段为 UTC epoch 毫秒，UTC 日界字段为 epochDay。
 */
public final class Results {

    private Results() {
    }

    /** 配方视图：state 为 SUBMITTED/REVIEWED/APPROVED，review 为最近一次审查报告（可空）。 */
    public record FormulaView(
            Long formulaId,
            String productCode,
            String productName,
            String categoryCode,
            Integer version,
            String state,
            Boolean reviewPassed,
            ReviewReport review,
            Long reviewedAt,
            Long approvedAt,
            boolean replayed) {
    }

    /** 备案视图：daysRemaining 仅复审观察期有值；截止日 = watchStartDay + 90，恰第 90 日受理。 */
    public record FilingView(
            Long filingId,
            Long formulaId,
            String productCode,
            Integer version,
            String status,
            Long watchStartDay,
            Long deadlineDay,
            Long daysRemaining,
            String suspendReason,
            Object snapshot,
            Long createdAt,
            Long finalizedAt,
            boolean replayed) {
    }

    public record ReviewView(Long formulaId, String state, ReviewReport report, boolean replayed) {
    }

    public record FilingReviewView(
            Long filingId,
            String status,
            boolean passed,
            ReviewReport report,
            Long reviewedAt,
            boolean replayed) {
    }

    public record ProductionView(
            Long filingId,
            String batchNo,
            String quantityKg,
            Long reportedAt,
            boolean replayed) {
    }

    public record StandardView(
            String additiveCode,
            String categoryCode,
            String maxAmount,
            Long updatedAt,
            List<Long> watchFilingIds,
            boolean replayed) {
    }

    public record SweepView(long todayEpochDay, List<Long> suspendedFilingIds) {
    }

    public record TrajectoryView(
            String productCode,
            List<FormulaView> formulas,
            List<FilingView> filings) {
    }
}

